import json
d = json.load(open('C:/Users/User/.claude.json','r',encoding='utf-8'))
# Check ALL mcpServers at every level
def find_mcp(obj, path=''):
    if isinstance(obj, dict):
        if 'unreal' in obj and isinstance(obj['unreal'], dict) and 'command' in obj.get('unreal',{}):
            print(f'Found at: {path}')
            print(json.dumps(obj['unreal'], indent=2))
        for k,v in obj.items():
            find_mcp(v, f'{path}.{k}')
find_mcp(d)
" 2>/dev/null
